def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    in_escape = False
    index = 0
    while index < len(line):
        ch = line[index]
        if not in_quotes:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        elif ch == '"':
            if in_escape:
                current.append('"')
                in_escape = False
            elif index + 1 < len(line) and line[index + 1] == '"':
                current.append('"')
                index += 1
            else:
                in_quotes = False
        elif ch == '\\':
            in_escape = True
        else:
            current.append(ch)
        index += 1
    fields.append(''.join(current))
    return fields
